# Illustrative state-count core; production code must add manifest, policy,
# error records, signing, non-overlap, inventory, and deterministic UTC slots.
$States = 'Bound','Closed','CloseWait','Closing','DeleteTCB','Established',
  'FinWait1','FinWait2','LastAck','Listen','SynReceived','SynSent','TimeWait'
$Counts = Get-NetTCPConnection -ErrorAction Stop | Group-Object State -NoElement
foreach ($State in $States) {
  $Match = $Counts | Where-Object Name -eq $State
  [ordered]@{
    schema_version=1; record_type='state'; state=$State.ToLowerInvariant()
    connection_count=if ($Match) {[int64]$Match.Count} else {0}
    sample_epoch=[DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
  } | ConvertTo-Json -Compress
}
